#pragma once

// U2 stones: MoreStoneVariants, RawMetalBricks, SturdyStone, CelebratoryLamps (docs/spec/stones.md).
//
// The blocks, shapes, recipes and loot tables are generated by tools/pack/stones.ps1. Natively this
// unit gates its content by config (recipes are not loaded and blocks are left out of the creative
// inventory when their module/option is off), sets the lamps' light from `lightLevel`, and makes raw
// metal bricks smelt 9x slower with Quark's XP.

#include <string_view>

namespace lp::feature::stones {

struct StonesConfig {
    int  version                 = 1;
    bool enableMoreStoneVariants = true;
    bool enableBricks            = true;
    bool enableChiseledBricks    = true;
    bool enablePillar            = true;
    bool enableRawMetalBricks    = true;
    bool enableSturdyStone       = true;
    bool enableCelebratoryLamps  = true;
    int  lightLevel              = 15;
};

/// Gate bits: every bit of an id's gate must be enabled for the id to be enabled.
inline constexpr unsigned G_msv      = 1u << 0; ///< enableMoreStoneVariants
inline constexpr unsigned G_bricks   = 1u << 1; ///< enableBricks
inline constexpr unsigned G_chiseled = 1u << 2; ///< enableChiseledBricks
inline constexpr unsigned G_pillar   = 1u << 3; ///< enablePillar
inline constexpr unsigned G_vslab    = 1u << 4; ///< U1 vslabs.json enableVerticalSlabs
inline constexpr unsigned G_rawmetal = 1u << 5; ///< enableRawMetalBricks
inline constexpr unsigned G_smelt    = 1u << 6; ///< U8 storage.json enableUtilityRecipes && smeltRawOreBlocks
inline constexpr unsigned G_sturdy   = 1u << 7; ///< enableSturdyStone
inline constexpr unsigned G_lamps    = 1u << 8; ///< enableCelebratoryLamps

/// Options of other units that gate content of this one (read from their config files; true when
/// the file or key is missing, so this unit works without them).
struct CrossUnit {
    bool verticalSlabs = true; ///< vslabs.json: enableVerticalSlabs
    bool smeltOreBlocks = true; ///< storage.json: enableUtilityRecipes && smeltRawOreBlocks
};
[[nodiscard]] CrossUnit& crossUnit();
/// Re-reads the other units' config files.
void refreshCrossUnit();

[[nodiscard]] bool gateEnabled(unsigned gate);
/// Gate of a block/item id or recipe id of this unit; 0 when the id is not ours.
[[nodiscard]] unsigned blockGate(std::string_view id);
[[nodiscard]] unsigned recipeGate(std::string_view id);
/// False only for ids of this unit whose gate is off.
[[nodiscard]] bool blockEnabled(std::string_view id);
[[nodiscard]] bool recipeEnabled(std::string_view id);
/// Number of block / recipe ids of this unit.
[[nodiscard]] int blockCount();
[[nodiscard]] int recipeCount();
/// Calls `fn(id, gate)` for every block id.
template <class F>
void forEachBlock(F&& fn);

/// The light the lamps emit (`lightLevel` clamped to 0..15).
[[nodiscard]] int lampLight();
[[nodiscard]] bool isLamp(std::string_view id);

/// Raw metal bricks smelt this many times slower than a normal item (Quark: 1800 / 900 ticks).
inline constexpr int kSmeltSlowdown = 9;
/// Smelting XP of raw metal bricks (0 = not raw metal bricks).
[[nodiscard]] float rawBricksXp(std::string_view id);
/// Furnace XP multiplier this unit gives a smelting result or input (0 = vanilla).
[[nodiscard]] float smeltResultXp(std::string_view id);

namespace detail {
struct GateEntry {
    std::string_view id;
    unsigned         gate;
};
[[nodiscard]] GateEntry const* blocksBegin();
[[nodiscard]] GateEntry const* blocksEnd();
} // namespace detail

template <class F>
void forEachBlock(F&& fn) {
    for (auto const* e = detail::blocksBegin(); e != detail::blocksEnd(); ++e) fn(e->id, e->gate);
}

} // namespace lp::feature::stones
